enable.example:
// client
const { NoClip, Key } = kcds.ui;
const { Vector3 } = kcds.math;

Key.bind('f3', () => {
  if (NoClip.isActive()) {
    NoClip.disable();
  } else {
    NoClip.enable({ mode: 'body', speed: 20 });
  }
});

// A character preview, with the camera circling the player at 2.5 m.
const feet = kcds.players.LocalPlayer.position;
NoClip.enable({
  mode: 'camera',
  showBody: true,
  orbit: { target: new Vector3(feet.x, feet.y, feet.z + 1.2), distance: 2.5 },
});

enable.exampleCs:
// client

Key.Bind("f3", new Action(() =>
{
    if (NoClip.IsActive())
    {
        NoClip.Disable();
    }
    else
    {
        NoClip.Enable(new { mode = "body", speed = 20 });
    }
}));

// A character preview, with the camera circling the player at 2.5 m.
var feet = LocalPlayer.Current!.Position;
NoClip.Enable(new { mode = "camera", showBody = true, orbit = new { target = new Vector3(feet.X, feet.Y, feet.Z + 1.2), distance = 2.5 } });

disable.example:
// client
const { NoClip } = kcds.ui;

NoClip.disable();
NoClip.disable({ keepPosition: false });

isAllowed.example:
// client
const { NoClip, Hud, Key } = kcds.ui;

Key.bind('f3', () => {
  if (!NoClip.isAllowed()) {
    Hud.showNotification('Flying is not allowed here.');
  } else if (NoClip.isActive()) {
    NoClip.disable();
  } else {
    NoClip.enable();
  }
});

isAllowed.exampleCs:
// client

Key.Bind("f3", new Action(() =>
{
    if (!NoClip.IsAllowed())
    {
        Hud.ShowNotification("Flying is not allowed here.");
    }
    else if (NoClip.IsActive())
    {
        NoClip.Disable();
    }
    else
    {
        NoClip.Enable();
    }
}));

isActive.example:
// client
const { NoClip } = kcds.ui;

if (NoClip.isActive()) {
  NoClip.disable();
}

getState.example:
// client
const flight = kcds.ui.NoClip.getState();
if (flight) {
  console.log(`${flight.mode} at ${flight.position}, ${flight.speed} m/s`);
}

getState.exampleCs:
// client
var flight = NoClip.GetState();
if (flight)
{
    Log.Info($"{flight["mode"]} at {flight["position"]}, {flight["speed"]} m/s");
}

setPose.example:
// client
const { Vector3 } = kcds.math;

kcds.ui.NoClip.setPose(new Vector3(1640, 2140, 50), new Vector3(1, 1, -0.5));

move.example:
// client: a slow fly-by steered by the script
setInterval(() => {
  kcds.ui.NoClip.move({ forward: 1, yaw: 2 }, 0.05);
}, 50);

move.exampleCs:
// client: a slow fly-by steered by the script
Timers.SetInterval(() =>
{
    NoClip.Move(new { forward = 1, yaw = 2 }, 0.05);
}, 50);

toScreen.example:
// client
const place = kcds.ui.NoClip.toScreen(new kcds.math.Vector3(1652.5, 2151.5, 37.5));
